def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd or cwd[0] != '/':
        return None

    link_count = 0
    max_links = 8

    # Normalize cwd to remove trailing slash (except for root)
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with current working directory if path is relative
    if not path or path[0] != '/':
        current = cwd
        components = path.split('/') if path else []
    else:
        current = '/'
        components = path.split('/')[1:]  # Skip empty first element from leading /

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this path is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Parse remaining components (after current component)
            remaining = components[i + 1:]

            # Parse target components
            if target[0] == '/':
                # Absolute link target
                target_components = target.split('/')[1:]
                current = '/'
            else:
                # Relative link target - relative to the directory containing the link
                link_dir = candidate.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                target_components = target.split('/')
                current = link_dir

            # Replace components with target components + remaining
            components = target_components + remaining
            i = 0
            continue

        # Not a symlink, just move current to this path
        current = candidate
        i += 1

    # Return result without trailing slash (except for root)
    if current == '/':
        return '/'
    else:
        return current.rstrip('/')

